// [4.8] Convierte un mensaje de site/datos (contrato v1) en filas para la tabla lecturas.
// Rack: una fila por posición. Ambiente: una fila con pos ''. Lo que no cumple el contrato se descarta.
const p = msg.payload;
if (!p || typeof p !== 'object' || p.schema !== 1) return null;
const id = String(p.node_id || '');
if (!/^[a-z0-9-]{1,32}$/.test(id)) return null;
const num = v => (typeof v === 'number' && isFinite(v)) ? v : null;
// Códigos de error: en el ambiente van en p.err; en el rack, en cada posición (q.err) y, si los hay, en p.err (mux).
const codigos = (...listas) => [].concat(...listas.map(l => Array.isArray(l) ? l : []))
    .filter(e => typeof e === 'string' && /^[A-Za-z0-9_]{1,40}$/.test(e)).join(',') || null;
const ts = Date.now();
const filas = [];
if (p.type === 'rack' && Array.isArray(p.positions)) {
    for (const q of p.positions) {
        if (!q || typeof q.id !== 'string' || !/^[A-Z]$/.test(q.id)) continue;
        filas.push({ ts, node_id: id, pos: q.id, temp: num(q.temp), hum: num(q.hum), dew_point: num(q.dew_point),
                     flame: q.flame === true ? 1 : (q.flame === false ? 0 : null),
                     pm1_0: null, pm2_5: null, pm10: null, err: codigos(p.err, q.err) });
    }
} else if (p.type === 'ambiente') {
    filas.push({ ts, node_id: id, pos: '', temp: num(p.temp), hum: num(p.hum), dew_point: num(p.dew_point), flame: null,
                 pm1_0: num(p.pm1_0), pm2_5: num(p.pm2_5), pm10: num(p.pm10), err: codigos(p.err) });
}
if (!filas.length) return null;
msg.payload = filas;
return msg;

// [4.8] Recibe el lote de 30 s (arreglo de arreglos de filas) y arma UNA transacción.
// Una sola escritura cada 30 s cuida la microSD (acuerdo de red-y-gateway.md).
const filas = [].concat(...(Array.isArray(msg.payload) ? msg.payload : []));
if (!filas.length) return null;
const COLS = ['ts', 'node_id', 'pos', 'temp', 'hum', 'dew_point', 'flame', 'pm1_0', 'pm2_5', 'pm10', 'err'];
const v = x => (x === null || x === undefined) ? 'NULL'
             : (typeof x === 'number' ? (isFinite(x) ? String(x) : 'NULL') : "'" + String(x).replace(/'/g, "''") + "'");
const partes = [];
for (let i = 0; i < filas.length; i += 200) {
    const vals = filas.slice(i, i + 200).map(f => '(' + COLS.map(c => v(f[c])).join(',') + ')');
    partes.push('INSERT INTO lecturas(' + COLS.join(',') + ') VALUES ' + vals.join(',') + ';');
}
msg.topic = 'PRAGMA synchronous=NORMAL; BEGIN; ' + partes.join(' ') + ' COMMIT;';
msg.filas = filas.length;
node.status({ fill: 'green', shape: 'dot', text: filas.length + ' filas · ' + new Date().toLocaleTimeString('es-MX') });
return msg;

// [4.8] Cada hora: recalcula el resumen de las últimas 3 horas y borra lecturas de más de DIAS días.
const DIAS = 30;
const H = 3600000;
const ahora = Date.now();
const desde = Math.floor(ahora / H) * H - 3 * H;
msg.topic =
    'INSERT OR REPLACE INTO resumen_hora ' +
    '(hora,node_id,pos,n,temp_avg,temp_min,temp_max,hum_avg,hum_min,hum_max,dew_avg,pm2_5_avg,pm2_5_max,pm10_avg,pm10_max,flama) ' +
    'SELECT (ts/' + H + ')*' + H + ', node_id, pos, COUNT(*), AVG(temp), MIN(temp), MAX(temp), AVG(hum), MIN(hum), MAX(hum), ' +
    'AVG(dew_point), AVG(pm2_5), MAX(pm2_5), AVG(pm10), MAX(pm10), MAX(flame) ' +
    'FROM lecturas WHERE ts >= ' + desde + ' GROUP BY 1, 2, 3; ' +
    'DELETE FROM lecturas WHERE ts < ' + (ahora - DIAS * 24 * H) + ';';
node.status({ fill: 'blue', shape: 'dot', text: 'resumen ' + new Date().toLocaleTimeString('es-MX') });
return msg;

// [4.8] Arma la consulta de la página Histórico. Entrada: '24h' o '7d' desde la página, o el refresco periódico.
// 24 h: promedio por minuto desde lecturas. 7 días: promedio por hora desde resumen_hora.
let rango = flow.get('rango_historico') || '24h';
if (msg.payload === '24h' || msg.payload === '7d') { rango = msg.payload; flow.set('rango_historico', rango); }
const H = 3600000, ahora = Date.now();
if (rango === '7d') {
    msg.topic = 'SELECT hora AS x, node_id, pos, temp_avg AS t, hum_avg AS h, pm2_5_avg AS p25, pm10_avg AS p10 ' +
                'FROM resumen_hora WHERE hora >= ' + (ahora - 7 * 24 * H) + ' ORDER BY 1';
} else {
    msg.topic = 'SELECT (ts/60000)*60000 AS x, node_id, pos, AVG(temp) AS t, AVG(hum) AS h, AVG(pm2_5) AS p25, AVG(pm10) AS p10 ' +
                'FROM lecturas WHERE ts >= ' + (ahora - 24 * H) + ' GROUP BY 1, 2, 3 ORDER BY 1';
}
msg.rango = rango;
return msg;

// [4.8] Convierte las filas de la consulta en series para las 3 gráficas y un resumen para la página.
// Por gráfica: primero un mensaje vacío (borra lo anterior) y luego un mensaje por serie con [{x, y}].
const filas = Array.isArray(msg.payload) ? msg.payload : [];
const nombre = f => f.pos ? f.node_id + ' ' + f.pos : f.node_id;
const r1 = v => (typeof v === 'number' && isFinite(v)) ? Math.round(v * 10) / 10 : null;
function series(campo, etiqueta) {
    const s = {};
    for (const f of filas) {
        const y = r1(f[campo]);
        if (y === null) continue;
        const k = etiqueta ? nombre(f) + ' ' + etiqueta : nombre(f);
        (s[k] = s[k] || []).push({ x: f.x, y: y });
    }
    return [{ payload: [] }].concat(Object.keys(s).sort().map(k => ({ topic: k, payload: s[k] })));
}
const temp = series('t'), hum = series('h');
const pm = series('p25', 'PM2.5').concat(series('p10', 'PM10').slice(1));
const nodos = [...new Set(filas.map(nombre))].sort();
const info = { payload: { rango: msg.rango, puntos: filas.length, nodos: nodos,
                          hora: new Date().toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' }) } };
node.status({ fill: 'green', shape: 'dot', text: msg.rango + ' · ' + filas.length + ' filas' });
return [temp, hum, pm, info];
